"""Tiny synthesizer: all sound effects and music are generated by code, so the
game ships without any audio files. Each song is composed once (intro, verse,
verse, chorus, verse) and cached as a .wav file in the save folder, so later
starts load it instantly. Music can be switched off on its own; sound effects
always stay on. Fails silently with no sound card."""

import math
import os
import random
import threading
import wave
from array import array
from operator import add

import pygame

from . import save

RATE = 22050
SONG_VERSION = 2   # bump when the songs change, so old cached .wav files are ignored


def _env(i, n, attack=0.005, release=0.6):
    t = i / RATE
    a = min(1.0, t / attack) if attack > 0 else 1.0
    r = max(0.0, 1 - (i / n) ** (1 / max(0.05, release)))
    return a * r


def _tone(freqs, dur, wave="square", vol=0.5, slide=0.0, noise=0.0, release=0.6, attack=0.005):
    n = int(RATE * dur)
    out = [0.0] * n
    rnd = random.Random(7)
    for f0 in freqs:
        ph = 0.0
        for i in range(n):
            f = f0 * (1 + slide * i / n)
            ph += f / RATE
            x = ph % 1.0
            if wave == "square":
                v = 1.0 if x < 0.5 else -1.0
            elif wave == "pulse":
                v = 1.0 if x < 0.25 else -1.0
            elif wave == "saw":
                v = 2 * x - 1
            elif wave == "tri":
                v = 4 * abs(x - 0.5) - 1
            else:
                v = math.sin(ph * math.tau)
            out[i] += v * vol / len(freqs) * _env(i, n, attack, release)
    if noise:
        for i in range(n):
            out[i] += rnd.uniform(-1, 1) * noise * _env(i, n, 0.001, 0.3)
    return out


def _mix_into(buf, samples, start):
    end = min(len(buf), start + len(samples))
    if end > start:
        buf[start:end] = map(add, buf[start:end], samples)


# ---------------------------------------------------------------------------
# Songs
# ---------------------------------------------------------------------------

MAJOR = [0, 2, 4, 5, 7, 9, 11]
MINOR = [0, 2, 3, 5, 7, 8, 10]
DORIAN = [0, 2, 3, 5, 7, 9, 10]
PHRYGIAN = [0, 1, 3, 5, 7, 8, 10]
HARMONIC = [0, 2, 3, 5, 7, 8, 11]

# kick, snare, hi-hat over 16 sixteenth notes
DRUMS = {
    "pop": ("x.......x.x.....", "....x.......x...", "x.x.x.x.x.x.x.x."),
    "disco": ("x...x...x...x...", "....x.......x...", "..x...x...x...x."),
    "rock": ("x.....x.x.....x.", "....x.......x...", "x.x.x.x.x.x.x.x."),
    "taiko": ("x..x..x...x.x...", "....x......x..x.", "x...x...x...x..."),
    "half": ("x.........x.....", "........x.......", "x...x...x...x..."),
    "boss": ("x.x.x.x.x.x.x.x.", "....x.......x..x", "xxxxxxxxxxxxxxxx"),
    "march": ("x...x...x...x...", "....x.......x.xx", "x.x.x.x.x.x.x.x."),
}

# Chords are scale degrees (0 = home chord). Verse and chorus have their own.
SONGS = {
    "menu": dict(bpm=122, root=60, scale=MAJOR, verse=[0, 5, 3, 4], chorus=[3, 4, 2, 5],
                 drums="pop", bass="octave", lead="square", arp="up"),
    0: dict(bpm=100, root=62, scale=MAJOR, verse=[5, 3, 4, 0], chorus=[1, 4, 0, 5],    # Sakura
            drums="taiko", bass="long", lead="tri", arp="pluck", penta=True),
    1: dict(bpm=126, root=57, scale=MINOR, verse=[0, 5, 2, 6], chorus=[3, 4, 0, 0],    # Neon
            drums="disco", bass="octave", lead="saw", arp="updown"),
    2: dict(bpm=152, root=52, scale=PHRYGIAN, verse=[0, 1, 0, 6], chorus=[5, 6, 0, 1],  # Magma
            drums="rock", bass="pulse", lead="square", arp=None),
    3: dict(bpm=138, root=50, scale=HARMONIC, verse=[0, 5, 3, 4], chorus=[5, 3, 6, 4],  # Ninja Ryu
            drums="boss", bass="pulse", lead="pulse", arp="up", pad=True, echo=True),
    "champion": dict(bpm=116, root=65, scale=MAJOR, verse=[0, 3, 4, 0], chorus=[3, 0, 4, 4],
                     drums="march", bass="walk", lead="square", arp="updown", pad=True),
}
ORDER = ["menu", 0, 1, 2, 3, "champion"]    # the title needs its song first

CELLS = [[2, 2], [1, 1, 2], [3, 1], [1, 1, 1, 1], [2, 1, 1], [4]]


def _motif(rnd):
    """Two bars of melody as (start, length, scale step from the chord root),
    in eighth notes. A step of None is a rest."""
    cells = [rnd.choice(CELLS) for _ in range(3)] + [rnd.choice([[4], [2, 2], [3, 1]])]
    notes, pos, step = [], 0, rnd.choice([0, 2, 4])
    for cell in cells:
        for ln in cell:
            rest = notes and rnd.random() < 0.12
            notes.append((pos, ln, None if rest else step))
            pos += ln
            step = max(-3, min(9, step + rnd.choice([-2, -1, -1, 1, 1, 2, 0, 3, -3])))
    return notes


def _vary(rnd, motif):
    """Same rhythm, new notes: keeps the phrase recognizable."""
    return [(p, ln, None if s is None else max(-3, min(9, s + rnd.choice([-2, -1, 0, 0, 1, 2]))))
            for p, ln, s in motif]


def compose(spec, seed):
    rnd = random.Random(str(seed))
    beat = 60 / spec["bpm"]
    six = beat / 4
    root, scale = spec["root"], spec["scale"]
    kick_p, snare_p, hat_p = DRUMS[spec["drums"]]

    def midi(idx):
        return root + scale[idx % 7] + 12 * (idx // 7)

    def hz(m):
        return 440 * 2 ** ((m - 69) / 12)

    cache = {}

    def note(m, dur, wave, vol, attack=0.005, release=0.5):
        k = (m, round(dur, 4), wave, vol, attack)
        if k not in cache:
            cache[k] = _tone([hz(m)], dur, wave, vol, release=release, attack=attack)
        return cache[k]

    kick = _tone([60], 0.16, "sine", 0.55, -0.5, release=0.3)
    snare = _tone([200], 0.13, "tri", 0.08, noise=0.3, release=0.3)
    hat = _tone([8000], 0.03, "sine", 0.0, noise=0.07, release=0.2)
    crash = _tone([5000], 1.2, "sine", 0.0, noise=0.12, release=0.9)

    m_verse, m_chorus = _motif(rnd), _motif(rnd)
    m_verse2 = _vary(rnd, m_verse)
    # (chords, melody per 2-bar phrase, melody octave, drums on, melody on)
    sections = [(spec["verse"][:1], None, 0, "intro"),
                (spec["verse"], [m_verse, m_verse2, m_verse, m_verse2], 0, "full"),
                (spec["verse"], [m_verse, m_verse2, m_verse, m_verse], 12, "full"),
                (spec["chorus"], [m_chorus, _vary(rnd, m_chorus), m_chorus, m_chorus], 0, "full"),
                (spec["verse"], [m_verse, m_verse2, m_verse, m_verse2], 0, "full")]
    bars = sum(len(ch) * 2 for ch, _, _, _ in sections)
    buf = [0.0] * int(RATE * beat * 4 * bars + RATE * 2)
    bar0 = 0
    for chords, melody, octave, kind in sections:
        _mix_into(buf, crash, int(RATE * bar0 * 4 * beat))
        for ci, ch in enumerate(chords):
            tones = [midi(ch), midi(ch + 2), midi(ch + 4)]
            for half in range(2):                      # each chord lasts two bars
                bar = bar0 + ci * 2 + half
                t0 = bar * 4 * beat
                # drums
                for s in range(16):
                    pos = int(RATE * (t0 + s * six))
                    if kick_p[s] == "x":
                        _mix_into(buf, kick, pos)
                    if kind == "full" and snare_p[s] == "x":
                        _mix_into(buf, snare, pos)
                    if hat_p[s] == "x":
                        _mix_into(buf, hat, pos)
                # bass (an octave below the chord root)
                b = midi(ch) - 12
                style = spec["bass"]
                for e in range(8):
                    pos = int(RATE * (t0 + e * 2 * six))
                    if style == "pulse":
                        _mix_into(buf, note(b, 2 * six * 0.9, "tri", 0.34), pos)
                    elif style == "octave":
                        _mix_into(buf, note(b + (12 if e % 2 else 0), 2 * six * 0.9, "tri", 0.34), pos)
                    elif style == "walk" and e % 2 == 0:
                        _mix_into(buf, note(b + [0, 7, 12, 7][e // 2], 4 * six * 0.9, "tri", 0.34), pos)
                    elif style == "long" and e % 4 == 0:
                        _mix_into(buf, note(b, 8 * six * 0.95, "tri", 0.3, release=0.8), pos)
                # pad: the chord held softly for the bar
                if spec.get("pad") and kind == "full":
                    for m in tones:
                        _mix_into(buf, note(m, 16 * six, "sine", 0.05, attack=0.25, release=0.7),
                                  int(RATE * t0))
                # arpeggio
                arp = spec["arp"]
                if arp and kind == "full":
                    seq = {"up": [0, 1, 2, 3], "updown": [0, 1, 2, 3, 2, 1],
                           "pluck": [0, 2, 1, 3]}[arp]
                    ladder = tones + [tones[0] + 12]
                    for e in range(8):
                        m = ladder[seq[e % len(seq)]]
                        wave, vol = ("sine", 0.09) if arp == "pluck" else ("pulse", 0.05)
                        _mix_into(buf, note(m, 2 * six * 0.6, wave, vol, release=0.3),
                                  int(RATE * (t0 + e * 2 * six)))
            # melody: one motif per two bars, landing on the home note at the end
            if melody:
                last_phrase = ci == len(chords) - 1
                for k, (p, ln, step) in enumerate(melody[ci]):
                    if step is None:
                        continue
                    idx = ch + step
                    if p % 4 == 0:                   # strong beats sit on a chord tone
                        idx = min((ch + d for d in (-3, 0, 2, 4, 7)), key=lambda x: abs(x - idx))
                    if last_phrase and k == len(melody[ci]) - 1:
                        idx = 7
                    if spec.get("penta") and idx % 7 in (3, 6):
                        idx += 1
                    m = midi(idx) + 12 + octave
                    pos = int(RATE * ((bar0 + ci * 2) * 4 * beat + p * 2 * six))
                    _mix_into(buf, note(m, ln * 2 * six * 0.9, spec["lead"], 0.11, release=0.6), pos)
        bar0 += len(chords) * 2
    buf = buf[:int(RATE * beat * 4 * bars)]
    if spec.get("echo"):
        d = int(RATE * 3 * six)
        buf[d:] = map(add, buf[d:], [x * 0.28 for x in buf[:-d]])
    peak = max(1e-6, max(buf), -min(buf))
    k = 0.85 / peak
    return [x * k for x in buf]


class Audio:
    def __init__(self, music_on=True):
        self.ok = False
        self.sounds = {}
        self.music = {}
        self.channel = None
        self.want = None
        self.music_on = music_on
        try:
            if not pygame.mixer.get_init():
                pygame.mixer.init(RATE, -16, 1, 512)
            self.freq, _, self.chans = pygame.mixer.get_init()
            pygame.mixer.set_reserved(1)       # channel 0 is only for music
            self.channel_music = pygame.mixer.Channel(0)
            self.ok = True
        except Exception:
            return
        self._make_sfx()
        threading.Thread(target=self._make_music, daemon=True).start()

    def _to_sound(self, samples):
        data = array("h")
        reps = self.chans
        step = RATE / self.freq
        n = int(len(samples) / step)
        for i in range(n):
            v = int(max(-1.0, min(1.0, samples[int(i * step)])) * 32000)
            for _ in range(reps):
                data.append(v)
        return pygame.mixer.Sound(buffer=data.tobytes())

    def _make_sfx(self):
        defs = {
            "hit": _tone([90], 0.22, "sine", 0.9, -0.6, noise=0.7, release=0.4),
            "bighit": _tone([70, 55], 0.45, "sine", 1.0, -0.7, noise=0.8, release=0.5),
            "block": _tone([880, 1320], 0.18, "tri", 0.5, -0.1, noise=0.2, release=0.3),
            "whoosh": _tone([200], 0.25, "sine", 0.05, 1.0, noise=0.35, release=0.8),
            "correct": _tone([660], 0.09, "square", 0.3) + _tone([990], 0.16, "square", 0.3),
            "wrong": _tone([220], 0.14, "saw", 0.35, -0.2) + _tone([160], 0.22, "saw", 0.35, -0.2),
            "tick": _tone([1200], 0.04, "square", 0.18, release=0.2),
            "select": _tone([520], 0.06, "square", 0.25, release=0.3),
            "confirm": _tone([520, 780], 0.08, "square", 0.3) + _tone([780, 1040], 0.18, "square", 0.3),
            "fire": _tone([300], 0.35, "saw", 0.3, 1.5, noise=0.15, release=0.7),
            "special": _tone([440, 660], 0.1, "square", 0.3) + _tone([660, 990], 0.28, "saw", 0.35, 0.3, noise=0.1),
            "super": _tone([330, 495], 0.08, "square", 0.3) + _tone([495, 742], 0.08, "square", 0.3)
            + _tone([660, 990, 1320], 0.4, "saw", 0.4, 0.4, noise=0.15),
            "ko": _tone([110, 82], 0.9, "saw", 0.6, -0.6, noise=0.3, release=0.8),
            "fight": _tone([392, 494, 587], 0.12, "square", 0.35) + _tone([523, 659, 784], 0.35, "square", 0.35),
        }
        for k, v in defs.items():
            self.sounds[k] = self._to_sound(v)

    def _make_music(self):
        for key in ORDER:
            try:
                self.music[key] = self._load_song(key)
            except Exception:
                pass

    def _load_song(self, key):
        path = os.path.join(save.data_dir(), f"music-v{SONG_VERSION}-{key}.wav")
        if os.path.exists(path):
            try:
                return pygame.mixer.Sound(path)
            except Exception:
                pass
        samples = compose(SONGS[key], key)
        try:
            os.makedirs(save.data_dir(), exist_ok=True)
            tmp = path + ".tmp"
            with wave.open(tmp, "wb") as w:
                w.setnchannels(1)
                w.setsampwidth(2)
                w.setframerate(RATE)
                w.writeframes(array("h", (int(x * 32000) for x in samples)).tobytes())
            os.replace(tmp, path)
            return pygame.mixer.Sound(path)
        except Exception:
            return self._to_sound(samples)

    def play(self, name):
        if self.ok and name in self.sounds:
            self.sounds[name].play()

    def play_music(self, key):
        """Music is generated in the background; it starts as soon as it is ready."""
        if self.want == key and self.channel:
            return
        self.stop_music()
        self.want = key

    def stop_music(self):
        self.want = None
        if self.channel:
            self.channel.fadeout(400)
            self.channel = None

    def update(self):
        if self.ok and self.music_on and self.want is not None and self.channel is None:
            snd = self.music.get(self.want)
            if snd:
                self.channel_music.play(snd, loops=-1, fade_ms=500)
                self.channel_music.set_volume(0.5)
                self.channel = self.channel_music

    def toggle_music(self):
        """Music on/off. Sound effects are not affected."""
        self.music_on = not self.music_on
        if self.channel:
            self.channel.fadeout(300)
            self.channel = None
        return self.music_on
